export const listAlertHistory = <ThrowOnError extends boolean = false>(options?: Options<ListAlertHistoryData, ThrowOnError>): RequestResult<ListAlertHistoryResponses, ListAlertHistoryErrors, ThrowOnError> => (options?.client ?? client).get<ListAlertHistoryResponses, ListAlertHistoryErrors, ThrowOnError>({
    requestValidator: async (data) => await z.object({
        body: z.never().optional(),
        path: z.never().optional(),
        query: zListAlertHistoryQuery.optional()
    }).parseAsync(data),
    responseValidator: async (data) => await zListAlertHistoryResponse.parseAsync(data),
    security: [{
            in: 'cookie',
            name: '__Host-estate_session',
            type: 'apiKey'
        }],
    url: '/api/v1/alerts/history',
    ...options
});
